				'defaultRoute'  => 'list/items',            // declared for parity; not consumed by current core
				'urlSuffix'     => '',
				'allowVars'     => false,                   // only route vars + per-rule allowVars survive
				'matchValue'    => 'empty',                 // a rule with an empty value is skipped when creating
				'mapVars'       => array(
					'news_id'  => 'id',
					'news_sef' => 'name',
				),
			),

			// Order matters: first match wins, both when parsing and when creating.
			'rules' => array(

				// ---- index / default list : /news ----
				''                                          => array('list/items',
					'allowVars'   => array('page'),
					'legacyQuery' => 'default.0.{page}',
