				'short-<id:{number}>-<name:{sefsecure}>'    => array('list/short',
					'allowVars'   => array('page'),
					'mapVars'     => array('category_id' => 'id', 'category_sef' => 'name'),
					'legacyQuery' => 'cat.{id}.{page}',
				),
				'short-<id:{number}>'                       => array('list/short',
					'allowVars'   => array('page'),
					'mapVars'     => array('category_id' => 'id'),
					'legacyQuery' => 'cat.{id}.{page}',
				),

				// ---- archives : /news/day-{yyyymmdd}, /news/month-{yyyymm} ----
				'day-<id:{number}>'                         => array('list/day',
					'allowVars'   => array('page'),
					'legacyQuery' => 'day.{id}.{page}',
				),
				'month-<id:{number}>'                       => array('list/month',
					'allowVars'   => array('page'),
					'legacyQuery' => 'month.{id}.{page}',
				),

				// ---- tag / author : /news/tag-{tag}, /news/author-{author} ----
				'tag-<tag:{secure}>'                        => array('list/tag',
					'allowVars'   => array('page'),
					'legacyQuery' => 'tag={tag}&page={page}',
				),
				'author-<author:{secure}>'                  => array('list/author',
					'allowVars'   => array('page'),
					'mapVars'     => array('user_name' => 'author'),
					'legacyQuery' => 'author={author}&page={page}',
				),

				/*
				 * OPTIONAL - upstream-shaped URLs kept alive for parsing only.
				 * They are declared LAST, so createUrl() never selects them and every
				 * emitted link stays hyphen-shaped; inbound /news/view/146/slug still
				 * resolves instead of 404ing. Leave commented out unless you actually
				 * need it: two URL shapes for one item is duplicate content, mitigated
				 * (not removed) by the canonical tag news.php already emits.
				 *
				'view/<id:{number}>/<category:{sefsecure}>/<name:{sefsecure}>' => array('view/item',
					'allowVars'   => array('page'),
					'mapVars'     => array('news_id' => 'id', 'category_sef' => 'category', 'news_sef' => 'name'),
					'legacyQuery' => 'extend.{id}',
				),
				'view/<id:{number}>/<name:{sefsecure}>' => array('view/item',
					'allowVars'   => array('page'),
					'mapVars'     => array('news_id' => 'id', 'news_sef' => 'name'),
					'legacyQuery' => 'extend.{id}',
				),
				'view/<id:{number}>' => array('view/item',
					'allowVars'   => array('page'),
					'mapVars'     => array('news_id' => 'id'),
					'legacyQuery' => 'extend.{id}',
				),
				'Category/<id:{number}>/<name:{sefsecure}>' => array('list/category',
					'allowVars'   => array('page'),
					'mapVars'     => array('category_id' => 'id', 'category_sef' => 'name'),
					'legacyQuery' => 'list.{id}.{page}',
				),
				'Short/<id:{number}>/<name:{sefsecure}>' => array('list/short',
					'allowVars'   => array('page'),
					'mapVars'     => array('category_id' => 'id', 'category_sef' => 'name'),
					'legacyQuery' => 'cat.{id}.{page}',
				),
				'Day/<id:{number}>'   => array('list/day',   'allowVars' => array('page'), 'legacyQuery' => 'day.{id}.{page}'),
				'Month/<id:{number}>' => array('list/month', 'allowVars' => array('page'), 'legacyQuery' => 'month.{id}.{page}'),
				'Tag/<tag:{secure}>'  => array('list/tag',   'allowVars' => array('page'), 'legacyQuery' => 'tag={tag}&page={page}'),
				'Author/<author:{secure}>' => array('list/author', 'allowVars' => array('page'), 'legacyQuery' => 'author={author}&page={page}'),
				 */
