	/**
	 * Admin callback - drives the label, description and examples shown in
	 * admin -> URL configuration, and the "Rebuild" SEF generator button.
	 * lan_eurl.php is loaded by that page; the defined() guards keep the file
	 * safe if admin() is ever called outside it.
	 */
	public function admin()
	{
		static $admin = null;

		if ($admin === null)
		{
			$admin = array(
				'labels' => array(
					'name'        => defined('LAN_EURL_CORE_NEWS') ? LAN_EURL_CORE_NEWS : 'News',
					'label'       => 'Friendly URLs with ID, hyphenated (Lite-compatible)',
					'description' => 'Legacy e107-2.4.x-Lite URL shape: /news/view-{id}-{slug}. Keeps indexed Lite URLs working natively, without redirects.',
					'examples'    => array(
						'{SITEURL}news/view-1-news-title',
						'{SITEURL}news/category-1-news-category',
					),
				),
				'generate'  => array('table' => 'news', 'primary' => 'news_id', 'input' => 'news_title', 'output' => 'news_sef'),
				'form'      => array(),
				'callbacks' => array(),
			);
		}

		return $admin;
	}
